/**
 * Teacher, student and family links from Sefaria and Wikidata: public/data-catalog-links.json,
 * generated by scripts/build_catalog_links.py. Ids are what drift between data sets (see
 * CLAUDE.md), so each entry carries the roster labels of both ends, and these tests fail when
 * an id now belongs to someone else. Also the merge rule that lets one relation stand for a
 * pair (lib/dataFoundation.ts::mergeDatasets), and that both loading paths read the file.
 */
import assert from 'node:assert/strict'
import graph from '../public/data.json'
import catalog from '../public/data-catalog-links.json'
import research from '../public/data-research-links.json'
import { mergeDatasets } from '../lib/dataFoundation'
import { getAllConnections } from '../lib/serverData'
import { readFileSync } from 'node:fs'

let passed = 0
let failed = 0

function test(name: string, fn: () => void) {
  try {
    fn()
    console.log(`  ok  ${name}`)
    passed++
  } catch (e) {
    console.log(`  FAIL ${name}`)
    console.log(`       ${(e as Error).message}`)
    failed++
  }
}

type Node = { id: string; label: string; birth_year?: number; death_year?: number; date_precision?: string }
type Link = { source: string; target: string; type: string }
type Entry = Link & { relation?: string; via: string[]; source_label: string; target_label: string; evidence_source: string }
const nodes = new Map((graph.nodes as Node[]).map(n => [n.id, n]))
const links = (catalog as { links: Entry[] }).links
const exact = (n: Node) => n.date_precision === 'exact' && n.birth_year != null && n.death_year != null && n.death_year - n.birth_year >= 20
const lesson = (l: { source: string; target: string; type: string }) =>
  l.type === 'teacher' ? `${l.source}>${l.target}` : `${l.target}>${l.source}`

console.log('\ndata-catalog-links.json')

test('the file is not empty or truncated', () => {
  assert.ok(links.length >= 80, `only ${links.length} links`)
  assert.deepEqual((catalog as { nodes: unknown[] }).nodes, [])
})

test('both ends are sages on the roster, still under the labels the file was built with', () => {
  const drifted = links.flatMap(l => [[l.source, l.source_label], [l.target, l.target_label]])
    .filter(([id, label]) => nodes.get(id)?.label !== label)
    .map(([id, label]) => `${id}: file says "${label}", roster says "${nodes.get(id)?.label}"`)
  assert.deepEqual([...new Set(drifted)], [], 'regenerate with scripts/build_catalog_links.py')
})

test('every link has a known type, a source catalogue and its evidence, and two different ends', () => {
  const bad = links.filter(l => !['teacher', 'family', 'influence', 'oppose', 'colleague'].includes(l.type)
    || l.source === l.target || !l.via.length || !l.via.every(v => v === 'sefaria' || v === 'wikidata')
    || !l.evidence_source)
  assert.deepEqual(bad, [])
})

test('no teacher is younger than his student, where both dates are exact', () => {
  const bad = links.filter(l => l.type === 'teacher')
    .filter(l => { const t = nodes.get(l.source)!, s = nodes.get(l.target)!; return exact(t) && exact(s) && t.birth_year! > s.birth_year! })
    .map(l => `${l.source_label} -> ${l.target_label}`)
  assert.deepEqual(bad, [])
})

test('a parent, grandparent or in-law comes first in a family link, where both dates are exact', () => {
  const bad = links.filter(l => l.type === 'family' && /parent|child|grand|father|mother|ancestor|descendant/.test(l.relation ?? ''))
    .filter(l => { const a = nodes.get(l.source)!, b = nodes.get(l.target)!; return exact(a) && exact(b) && a.birth_year! > b.birth_year! })
    .map(l => `${l.source_label} -> ${l.target_label} (${l.relation})`)
  assert.deepEqual(bad, [])
})

test('nobody is both teacher and student of the same sage, here or against the site', () => {
  const site = [...(graph.links as Link[]), ...((research as { links: Link[] }).links)]
    .filter(l => l.type === 'teacher' || l.type === 'student').map(lesson)
  const all = new Set([...site, ...links.filter(l => l.type === 'teacher').map(lesson)])
  const both = [...all].filter(k => { const [a, b] = k.split('>'); return all.has(`${b}>${a}`) })
  assert.deepEqual(both, [])
})

test('no link repeats one the site already states', () => {
  const site = (graph.links as Link[]).filter(l => l.type === 'teacher' || l.type === 'student').map(lesson)
  const repeated = links.filter(l => l.type === 'teacher' && site.includes(lesson(l))).map(l => `${l.source_label} -> ${l.target_label}`)
  assert.deepEqual(repeated, [])
})

console.log('\nmergeDatasets: one edge per relation')

const merge = (links: Array<{ source: string; target: string; type: string }>) =>
  mergeDatasets([{ nodes: [], links }], []).connections.map(c => `${c.source}${c.type === 'family' ? '~' : '>'}${c.target}:${c.type}`)

test('an influence link gives way to a teacher or family link for the same pair', () => {
  assert.deepEqual(merge([
    { source: 'a', target: 'b', type: 'influence' }, { source: 'a', target: 'b', type: 'teacher' },
    { source: 'd', target: 'c', type: 'influence' }, { source: 'c', target: 'd', type: 'family' },
    { source: 'e', target: 'f', type: 'influence' },
  ]), ['a>b:teacher', 'c~d:family', 'e>f:influence'])
})

test('teacher a->b and student b->a are one relation, kept once', () => {
  assert.deepEqual(merge([
    { source: 'a', target: 'b', type: 'teacher' }, { source: 'b', target: 'a', type: 'student' },
    { source: 'c', target: 'd', type: 'student' },
  ]), ['a>b:teacher', 'c>d:student'])
})

test('other kinds of link are left as they are', () => {
  assert.deepEqual(merge([
    { source: 'a', target: 'b', type: 'oppose' }, { source: 'a', target: 'b', type: 'influence' },
    { source: 'a', target: 'b', type: 'colleague' },
  ]), ['a>b:oppose', 'a>b:influence', 'a>b:colleague'])
})

console.log('\nloading')

test('the server path merges the file', () => {
  const have = new Set(getAllConnections().map(c => `${c.source}>${c.target}:${c.type}`))
  const missing = links.filter(l => !have.has(`${l.source}>${l.target}:${l.type}`)).map(l => `${l.source_label} -> ${l.target_label}`)
  assert.deepEqual(missing, [])
})

test('the browser path fetches the file', () => {
  assert.match(readFileSync(new URL('../lib/appShellDataLoader.ts', import.meta.url), 'utf8'), /'\/data-catalog-links\.json'/)
})

console.log(`\n${passed} passed, ${failed} failed`)
if (failed) process.exit(1)
